package com.rulecraft.decisionops.tests.api;
import com.rulecraft.decisionops.identity.security.CurrentUser;import com.rulecraft.decisionops.tests.DecisionTestService;import com.rulecraft.decisionops.tests.DecisionTestService.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/tests")
public class DecisionTestController {private final DecisionTestService service;public DecisionTestController(DecisionTestService service){this.service=service;}@GetMapping List<TestCaseView> list(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication authentication){return service.list(CurrentUser.require(authentication),projectId,serviceId);}@PostMapping @ResponseStatus(HttpStatus.CREATED)TestCaseView create(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody TestCaseCommand body,Authentication authentication){return service.create(CurrentUser.require(authentication),projectId,serviceId,body);}@PutMapping("/{testId}")TestCaseView update(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID testId,@RequestBody TestCaseCommand body,Authentication authentication){return service.update(CurrentUser.require(authentication),projectId,serviceId,testId,body);}@DeleteMapping("/{testId}")@ResponseStatus(HttpStatus.NO_CONTENT)void remove(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID testId,@RequestParam long version,Authentication authentication){service.remove(CurrentUser.require(authentication),projectId,serviceId,testId,version);}@PostMapping("/{testId}/runs")@ResponseStatus(HttpStatus.CREATED)TestRunView run(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID testId,Authentication authentication){return service.run(CurrentUser.require(authentication),projectId,serviceId,testId);}@GetMapping("/{testId}/runs")List<TestRunView> history(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID testId,Authentication authentication){return service.history(CurrentUser.require(authentication),projectId,serviceId,testId);}}
